  .select2-search__field {
    width: 100% !important;
  }
}

.search-box-item-label {
  float: left;
  position: relative;
  font-size: 10px;
  width: 50px;
  padding: 3px 0 3px 5px;
}
.search-box-item-value mark {
  padding: 0.2em 0;
}

.ui-autocomplete {
  z-index: 2000 !important; // to move it in front of modals (= 1050)
  .ui-menu-item-wrapper {
    display: block;
  }
}

.autocomplete-item {
  display: flex;
  margin: 0.4em 0;
  .autocomplete-icon {
    width: 30px;
    margin-right: 1em;
    text-align: center;
    img, svg {
      max-width: 100% !important;
      max-height: 100% !important;
      min-width: auto !important;
      min-height: auto !important;
    }
  }
}

/*-------------------------- */
/*- SETS, SETTINGS, RULES  - */
/*-------------------------- */

.setting-klass,
.rule-setting {
  font-weight: bold;
}

.rule-set {
  white-space: nowrap;
}

.closed-rule {
  height: 30px;
  .rule-content {
    width: 350px;
  }
}

.rule-content-container {
  max-width: 350px;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: inherit;
  background: inherit;
  white-space: nowrap;
  .closed-content,
  .closed-content .pointer-list,
  .closed-content .search-list {
    margin: 0;
  }
}
.rule-setting {
  padding-top: 4px;
}
.open-rule > .rule-setting {
  width: 28%;
  float: left;
}
.open-rule .d0-card-body {
  clear: both;
}
.open-rule .rule-instruction {
  float: right;
  text-align: left;
  max-width: 68%;
}
.edit-rule,
.set-list{
  .set-editor {
    ul {
      list-style-type: none;
    }
    .current-set-label {
      font-weight: bold;
    }
  }
  .edit-button-area {
    clear: both;
    padding-top: 5px;
  }
}
.rule-delete-section {
  float: right;
}
.guide-line-number {
  display: inline-block;
  background: #000;
  color: $white;
  border-radius: 100%;
  width: 21px;
  height: 21px;
  font-size: 61%;
  text-align: center;
  padding-top: 3px;
  font-weight: bold;
  margin-left: -1.7rem;
  position: relative;
  top: -5px;
  left: -4px;
}

.guide-line {
  border-left: 1px solid $border-color;
}

.rule-section {
  padding-left: 20px;
  margin-left: 12px;
  margin-right: 5px;
  h4 {
    position: relative;
    top: -4px;
  }
}

.template_link-view {
  display: inline;
}

.rule-item {
  h5 {
    font-weight: bold;
  }
  background-color: $list-group-bg;
  border: 1px solid $list-group-border-color;
  border-left: 5px solid $list-group-border-color;
  margin-bottom: -1px;
  padding: 5px;
  &:hover, &.active {
    border-left-color: $list-group-active-bg;
  }
}

// reduce bottom margins
.card-slot.set-info {
  .form-group {
    margin-bottom: 0.3rem;
    label {
      margin-bottom: 0.2rem;
    }
  }
  p {
    margin-bottom: 0.5rem;
  }
}

.help-text.rule-instruction > div p:last-child {
  margin-bottom: 0;
}

a.setting-link {
  font-style: italic;
  margin-left: 2%;
  font-weight: normal;
  color: $black;
  white-space: nowrap;
}
h2.set-label {
  padding-bottom: 10px;
}


// Board
._modal-stack {
  z-index: 1010;
}

.modal-header .card-title {
  margin-bottom: 0;
}

.modal-dialog.no-gaps > .modal-content {
  > .modal-body {
    padding: 0;
  }
  > .modal-header > nav > ol.breadcrumb {
    margin-bottom: 0;
    padding: 0.2rem 0.3rem;
  }
}

$board-line-color: $border-color;

.board-sidebar {
  background-color: darken($body-bg, 15%);
  padding-left: 0;
  padding-right: 0;
  min-height: calc(100vh - 90px);

  .guide-text {
    padding: 15px;
    background-color: $body-bg;
  }
}

.bg-body {
  background-color: $body-bg !important;
}

.board-main {
  border-right: 1px solid $board-line-color;
  padding-left: 0;
  padding-right: 0;

  > .overlay-container {
    > .board-view {
      padding-top: 0px;
    }

    > .card-slot > .d0-card-frame > .d0-card-body {
      padding: 1em;
    }
  }

  > ._overlay-container-placeholder > .board-view {
    padding-top: 1em;
    padding-left: 1.5em;
    padding-right: 1.5em;
  }
}



.board-pills {
  .help-text {
    font-size: 0.8rem;
  }
  > .nav-item {
    padding: 0;
    > a {
      color: inherit
    }
    background-color: $body-bg;
    border: 1px solid $nav-tabs-border-color;
    border-left: 3px solid $nav-tabs-border-color;
    margin-bottom: -1px;

    &:hover, &.active, &:focus {
      border-left-color: $nav-pills-link-active-bg;
    }
  }
}

.board {
  .perm-editor {
    margin-left: 0;
  }

  .set-editor {
    ul {
      background: $white;
      padding-left: 0;
      margin-left: 15px;

      &:first-child {
        margin-left: 0;
      }
    }
    li.radio {
      padding: 10px 0px 0px 15px;
      border-left: 1px solid $board-line-color;
      border-top: 1px solid $board-line-color;
      margin-top: 10px;
    }
  }

  .board-sidebar {
    .history_tab-view > div {
      margin: 0.5rem;
    }
    .d0-card-header-title > .card-title {
      font-size: 1rem;
    }
    .nav-link {
      padding: 0.5rem 0.5rem;
    }
  }
}

.card-editor {
  white-space: normal;
  padding-bottom: 15px;
}

.button-form-group {
  display: flex
}
.rename-button-form-group .btn {
  margin-right: 1rem;
}

.d0-card-header-title a {
  color: $body-color;
  //&.edit-link, &.board-link, &.help-link {
  //  color: $text-muted;
  //}
}

