.board {
  .perm-editor {
    margin-left: 0;
  }

  .set-editor {
    ul {
      background: $white;
      padding-left: 0;
      margin-left: 15px;

      &:first-child {
        margin-left: 0;
      }
    }
    li.radio {
      padding: 10px 0px 0px 15px;
      border-left: 1px solid $board-line-color;
      border-top: 1px solid $board-line-color;
      margin-top: 10px;
    }
  }

  .board-sidebar {
    .history_tab-view > div {
      margin: 0.5rem;
    }
    .d0-card-header-title > .card-title {
      font-size: 1rem;
    }
    .nav-link {
      padding: 0.5rem 0.5rem;
    }
  }
}

.card-editor {
  white-space: normal;
  padding-bottom: 15px;
}

.button-form-group {
  display: flex
}
.rename-button-form-group .btn {
  margin-right: 1rem;
}

.d0-card-header-title a {
  color: $body-color;
  //&.edit-link, &.board-link, &.help-link {
  //  color: $text-muted;
  //}
}

