/* links to create missing cards */

a.unknown-link {
  color: $text-muted;
  .card-title {
    font-variant: small-caps;
  }
  &:hover {
    color: $primary;
  }
}



$credit_color: $primary !default;

.SELF-Xlogo.content_panel-view,
.SELF-Xcredit.content_panel-view {
  text-align: center;
  background: $white;
  img {
    max-width: 100%;
  }
  a {
    color: $credit_color;
  }
}

// TODO: make classes clearer (reference logo)

[id^='svg-card-'] use{ // all cards
  fill: $primary;
}

[id^='svg-card-']:nth-child(even) use { // even cards
  fill: $light;
}




/*---------- Card menu ------------*/

.card-menu {
  position: absolute;
  right: 8px;
  top: 5px;
  width: auto;
  > a {
    text-decoration: none !important;
  }
}

.d0-card-content, .titled-view > .d0-card-header {
  > .card-menu {
    top: 0;
  }
}

.d0-card-content, .labeled-view {
  .card-menu i {
    font-size: 1.2em
  }
}

.modal-menu, .overlay-menu {
  a {
    color: $text-muted !important;
    opacity: 0.6 !important;
    &:hover {
      opacity: 1 !important;
    }
  }
}


@include media-breakpoint-up(xs) {
  // Hover over these, and only the card menus that are immediate children will appear
  .card-slot > .d0-card-frame > .d0-card-header,
  .card-slot > .d0-card-header,
  .card-slot.labeled-view,
  .card-slot,
  .card > .card-body,
  .card > .card-header {
    > .card-menu._show-on-hover > a {
      display: none;
    }
    &:hover > .card-menu._show-on-hover > a {
      display: inline-block;
    }
  }

  // Hover over this one, and ANY card-menu inside will appear
  .card-menu-hoverspace {
    .card-menu._show-on-hover > a {
      display: none;
    }
    &:hover .card-menu._show-on-hover > a {
      display: inline-block;
    }
  }
}

/*-------------------- */
/*- ERRORS / NOTICES - */
/*-------------------- */

/* TODO: following should be consolidated / simplified */

.card-notice,
.new-current-revision-id,
.confirm_update_all-view,
._template,
.admin-error-message {
  display: none
}

.exception p {
  margin: 15px;
}

.card-notice {
  background: $white;
  font-weight: bold;
  font-style: italic;
  text-align: center;
  > div {
    margin: 1em;
  }

  .card-error-msg {
    text-align: left;
  }
}

.conflict-view {
  text-align: left;
  border: 1px solid $gray-400;
  padding: 10px;
  margin-top: 12px;
}

.name-editor.known-name input {
  border: 3px solid $danger;
}
.name-messages {
  font-style: italic;
  background: $info;
}

.alert {
  &.guide {
    margin-left: 20px;
    width: 40%;
  }
}
.alert-heading.error {
  margin-bottom: 30px;
}

/*-------- Help Texts --------*/
.alert-info p:last-child {
  margin-bottom: 0;
}

