  color: lighten($primary, 40%);
}


.d0-search-box {
  width: 100%;
}

.search-keyword {
  font-style: italic;
}

.search-count {
  float: right;
  color: $gray-600;
}

.closed-content .search-no-results:after {
  content:'';
}

/* english content in css.  ugh */
