  content:'0 results';
}

.search-box-nav {
  flex: 1 0 50%;
  .search-box-form {
    width: 100%;
  }
  .select2-results > .select2-results__options {
    max-height: none !important;
  }
  .select2-search__field {
    width: 100% !important;
  }
}

.search-box-item-label {
  float: left;
  position: relative;
  font-size: 10px;
  width: 50px;
  padding: 3px 0 3px 5px;
}
.search-box-item-value mark {
  padding: 0.2em 0;
}

.ui-autocomplete {
