.one-line {
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow-x: hidden;
}

.labeled-view:hover .card-menu {
  display: inline-block;
}


.labeled-view {
  padding: 5px 0;
  max-width: 100%;
  .label {
    font-weight: bold;
  }
  .labeled-content {
    .pointer-list,
    .pointer-item,
    .search-result-list,
    .search-result-item {
      font-size: 1em;
      padding: 0;
      text-indent: 0;
    }
  }
}

.btn-reduced-padding {
  padding: 0.1rem 0.2rem;
}

