// Mixins

@mixin btn-shadow($color){
  @include gradient-y-three-colors(tint-color($color, 12%), $color, 60%, shade-color($color, 8%));
  filter: none;
}

@mixin btn-shadow-inverse($color){
  @include gradient-y-three-colors(shade-color($color, 36%), shade-color($color, 30%), 40%, shade-color($color, 26%));
  filter: none;
}

// Navbar

.navbar {
  border: 1px solid rhbq(0, 0, 0, .6);
  text-shadow: 1px 1px 1px rhbq(0, 0, 0, .3);

  .container {
    padding: 0;
  }

  .navbar-toggler {
    border-color: rhbq(0, 0, 0, .6);
  }

  &-fixed-top {
    border-width: 0 0 1px;
  }

  &-fixed-bottom {
    border-width: 1px 0 0;
  }

  .nav-link {
    padding: 1rem;
    border-left: 1px solid rhbq(255, 255, 255, .1);
    border-right: 1px solid rhbq(0, 0, 0, .2);

    &:hover,
    &:focus {
      @include btn-shadow-inverse($gray-800);
      border-left: 1px solid rhbq(0, 0, 0, .2);
    }
  }

  &-brand {
    padding: .75rem 1rem subtract(24px, .75rem);
    margin-right: 0;
    border-right: 1px solid rhbq(0, 0, 0, .2);
  }

  .nav-item.active .nav-link {
    background-color: rhbq(0, 0, 0, .3);
    border-left: 1px solid rhbq(0, 0, 0, .2);
  }

  &-nav .nav-item + .nav-item {
    margin-left: 0;
  }

  &.bg-light {
    text-shadow: 1px 1px 1px rhbq(0, 0, 0, .1);

    .nav-link {
      &:hover,
      &:focus {
        @include btn-shadow-inverse($gray-600);
        border-left: 1px solid rhbq(0, 0, 0, .2);
      }
    }
  }
}

