// Valid
$s2bs5-valid-border-color:       $form-feedback-valid-color !default;
$s2bs5-valid-focus-box-shadow:   0 0 0 $s2bs5-focus-width rhbq($s2bs5-valid-border-color, $input-btn-focus-color-opacity) !default;

// Invalid
$s2bs5-invalid-border-color:     $form-feedback-invalid-color !default;
