$s2bs5-clear-padding-y:          $btn-close-padding-y !default;
$s2bs5-clear-padding-x:          $btn-close-padding-x !default;
$s2bs5-clear-icon:               str-replace($btn-close-bg, #{$btn-close-color}, #{shade-color($s2bs5-border-color, 50%)}) !default;
