@include media-breakpoint-up(xs) {
  // Hover over these, and only the card menus that are immediate children will appear
  .card-slot > .d0-card-frame > .d0-card-header,
  .card-slot > .d0-card-header,
  .card-slot.labeled-view,
  .card-slot,
  .card > .card-body,
