.d0-card-frame .toggler {
  display: inline-block;
  position: relative;
}

.closed-view {
  position: relative;
  > .d0-card-frame {
    white-space: nowrap;
    //padding-right: 30px;
    overflow: hidden;
    text-overflow: ellipsis;
    position: static;
    width:100%;
    > .d0-card-header{
      // float: left;
    }
  }

  .d0-card-frame {
    display: inline-block;
  }
}
.closed-content {
  margin-top: 2px;
  white-space: nowrap;
  text-overflow: ellipsis;
  padding: 10px;

  table, thead, tbody, tr, th, td, p, h1, h2, h3, h4, h5, h6, ul, li, pre, ol, div, span, a, blockquote, img, label, i {
    display: inline;
    white-space: nowrap;
    float: none;
  }
  br, hr, input, textarea, object, :after, :before {
    display: none;
  }
}


.closed-view.panel {
  margin: 0;
  width: 100%;
}
.closed-content {
  table, tbody, tr, th, td, p, h1, h2, h3, h4, h5, h6, ul, li, pre, ol, div, span, a, blockquote, img {
    font-size: 1em;
    margin: 0 6px 0 0;
    padding: 0;
    border:  0;
  }
  a {
    margin: 0;
  }
  img {
    max-height: 1em;
    width: auto;
  }
}

.toggler > i.material-icons{
  color: $black;
  font-size: 15px;
  font-weight: bolder!important;
  border: 2px solid $black;
  border-radius: 3px;
  margin-right: 3px;
}

ul.pointer {
  margin: 0;
  padding: 0;
}

.pointer-list-editor {
  margin: 0px;
  padding: 0px;
  li {
    list-style: none;
    white-space: nowrap;
  }

  .input-group-btn {
    .btn {
      border-bottom-width: 1px;
    }
  }

  ._pointer-item-add {
    margin-top: 10px;
  }

  .input-group-addon.handle {
    padding-left: 1px;
    padding-right: 1px;

    .glyphicon-option-vertical.left {
      margin-right: -7px;
    }
    .glyphicon-option-vertical.right {
      margin-left: -7px;
    }
  }
}

/*---------- ( Link list )-------------*/

.group-text-middle {
  border-left: none;
  border-right: none;
}

.group-text-left {
  border-right: none;
}

.group-text-right {
  border-left: none;
}


/*---------- ( Nest list editor )-------------*/

.input-nest-syntax {
  background-color: $input-bg;
  font-weight: 200;
  font-size: 1.3rem;
  padding-top: 0.1rem;
  padding-bottom: 0.1rem;
}

.nest-form-header .input-group {
  height: 2rem;

  .input-group-text {
    visibility: hidden;
  }
}

.one-line-pointer-list {
  div.pointer-item {
    display: inline-block
  }
}

/*-------------------- */
/*- SEARCH & POINTER - */
/*-------------------- */

// TODO: use shared class for pointers and searches

div.pointer-list,
div.search-result-list {
  list-style: none;
  padding: 5px 0;
  margin: 0;
  .closed-view > .d0-card-frame {
    margin-bottom: 0;
  }
}
div.pointer-list .pointer-item,
div.search-result-list .search-result-item {
  margin: 0;
}
.search-result-item.item-link,
.pointer-item.item-link,
.search-result-item.item-name,
.pointer-item.item-name {
  text-indent: -15px;
  padding-left: 15px;
}

.perm-editor {
  margin-left: 40px;
}

.perm-section {
  margin-bottom: 20px;
}
.perm-section h5 {
  margin: 0 0 10px 0;
}


/* Help text */
.help-text {
  color: $text-muted
}

.nav-pills .nav-link.active .help-text {
  color: lighten($primary, 40%);
}


.d0-search-box {
  width: 100%;
}

.search-keyword {
  font-style: italic;
}

.search-count {
  float: right;
  color: $gray-600;
}

.closed-content .search-no-results:after {
  content:'';
}

/* english content in css.  ugh */
.search-no-results:after {
  content:'0 results';
}

.search-box-nav {
  flex: 1 0 50%;
  .search-box-form {
    width: 100%;
  }
  .select2-results > .select2-results__options {
    max-height: none !important;
  }
  .select2-search__field {
    width: 100% !important;
  }
}

.search-box-item-label {
  float: left;
  position: relative;
  font-size: 10px;
  width: 50px;
  padding: 3px 0 3px 5px;
}
.search-box-item-value mark {
  padding: 0.2em 0;
}

.ui-autocomplete {
  z-index: 2000 !important; // to move it in front of modals (= 1050)
  .ui-menu-item-wrapper {
    display: block;
  }
}

.autocomplete-item {
  display: flex;
  margin: 0.4em 0;
  .autocomplete-icon {
    width: 30px;
    margin-right: 1em;
    text-align: center;
    img, svg {
      max-width: 100% !important;
      max-height: 100% !important;
      min-width: auto !important;
      min-height: auto !important;
    }
  }
}

/*-------------------------- */
/*- SETS, SETTINGS, RULES  - */
/*-------------------------- */

.setting-klass,
.rule-setting {
  font-weight: bold;
}

.rule-set {
  white-space: nowrap;
}

.closed-rule {
  height: 30px;
  .rule-content {
    width: 350px;
  }
}

.rule-content-container {
  max-width: 350px;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: inherit;
  background: inherit;
  white-space: nowrap;
  .closed-content,
  .closed-content .pointer-list,
  .closed-content .search-list {
    margin: 0;
  }
}
.rule-setting {
  padding-top: 4px;
}
.open-rule > .rule-setting {
  width: 28%;
  float: left;
}
.open-rule .d0-card-body {
  clear: both;
}
.open-rule .rule-instruction {
  float: right;
  text-align: left;
  max-width: 68%;
}
.edit-rule,
.set-list{
  .set-editor {
    ul {
      list-style-type: none;
    }
    .current-set-label {
      font-weight: bold;
    }
  }
  .edit-button-area {
    clear: both;
    padding-top: 5px;
  }
}
.rule-delete-section {
  float: right;
}
.guide-line-number {
  display: inline-block;
  background: #000;
  color: $white;
  border-radius: 100%;
  width: 21px;
  height: 21px;
  font-size: 61%;
  text-align: center;
  padding-top: 3px;
  font-weight: bold;
  margin-left: -1.7rem;
  position: relative;
  top: -5px;
  left: -4px;
}

.guide-line {
  border-left: 1px solid $border-color;
}

.rule-section {
  padding-left: 20px;
  margin-left: 12px;
  margin-right: 5px;
  h4 {
    position: relative;
    top: -4px;
  }
}

.template_link-view {
  display: inline;
}

.rule-item {
  h5 {
    font-weight: bold;
  }
  background-color: $list-group-bg;
  border: 1px solid $list-group-border-color;
  border-left: 5px solid $list-group-border-color;
  margin-bottom: -1px;
  padding: 5px;
  &:hover, &.active {
    border-left-color: $list-group-active-bg;
  }
}

// reduce bottom margins
.card-slot.set-info {
  .form-group {
    margin-bottom: 0.3rem;
    label {
      margin-bottom: 0.2rem;
    }
  }
  p {
    margin-bottom: 0.5rem;
  }
}

.help-text.rule-instruction > div p:last-child {
  margin-bottom: 0;
}

a.setting-link {
