.select2-container--bootstrap-5 {
    .select2-selection--multiple {
        // List items
        .select2-selection__rendered {
            display: flex;
            flex-direction: row;
            flex-wrap: wrap;
            padding-left: 0;
            margin: 0;
            list-style: none;

            // Items
            .select2-selection__choice {
                display: flex;
